diff --git a/scripts/generate-runner-manifest.mjs b/scripts/generate-runner-manifest.mjs
new file mode 100644
index 0000000..fd871a7
--- /dev/null
+++ b/scripts/generate-runner-manifest.mjs
@@ -0,0 +1,123 @@
+#!/usr/bin/env node
+/***
+ * MARK: generate-runner-manifest
+ * @description Builds + signs the release manifest for the GitHub Releases
+ *   update channel (Option A, ADR 0012). Reads the per-platform tarballs in
+ *   a dist dir, emits manifest.json (schema 1: component/version/assets
+ *   with sha256+size, assetBase, releasedAt), and writes
+ *   manifest.json.minisig in minisign format using the release SECRET key
+ *   from the RUNNER_RELEASE_SIGNING_KEY env var (base64 of the raw 32-byte
+ *   Ed25519 seed — CI injects it from GitHub Secrets; the public half is
+ *   pinned in runner/updates/verify.js and scripts/runner-pinned-key/).
+ * @example RUNNER_RELEASE_SIGNING_KEY=$(...) node scripts/generate-runner-manifest.mjs --dir dist/ --version 1.2.3
+ ***/
+import crypto from "node:crypto";
+import fs from "node:fs";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+
+const HERE = path.dirname(fileURLToPath(import.meta.url));
+const REPO_ROOT = path.resolve(HERE, "..");
+
+export const SUPPORTED_TARGETS = [
+	["linux", "x64"],
+	["linux", "arm64"],
+	["darwin", "x64"],
+	["darwin", "arm64"],
+];
+
+const parseArgs = (argv) => {
+	const out = {};
+	for (let i = 0; i < argv.length; i += 1) {
+		const arg = argv[i];
+		if (arg.startsWith("--")) {
+			const key = arg.slice(2);
+			out[key] = argv[i + 1] && !argv[i + 1].startsWith("--") ? argv.splice(i + 1, 1)[0] : "true";
+		}
+	}
+	return out;
+};
+
+export const sha256FileHex = (filePath) => {
+	const hash = crypto.createHash("sha256");
+	hash.update(fs.readFileSync(filePath));
+	return hash.digest("hex");
+};
+
+const pkcs8DerFor = (privRaw) =>
+	Buffer.concat([Buffer.from("302e020100300506032b657004220420", "hex"), Buffer.from(privRaw)]);
+
+export const minisignSign = ({ messageBytes, secretSeedHex, keynumHex }) => {
+	const priv = crypto.createPrivateKey({
+		key: pkcs8DerFor(Buffer.from(secretSeedHex, "hex")),
+		format: "der",
+		type: "pkcs8",
+	});
+	const sig = crypto.sign(null, Buffer.from(messageBytes), priv);
+	const envelope = Buffer.concat([
+		Buffer.from([0x45, 0x64]),
+		Buffer.from(keynumHex, "hex"),
+		sig,
+	]).toString("base64");
+	return `untrusted comment: kainbain runner release signature\n${envelope}\n`;
+};
+
+export const buildManifest = ({ version, dir, tag }) => {
+	const clean = String(version || "").trim().replace(/^v/, "");
+	// Full semver incl. canary pre-releases (`1.2.3-rc.1`): the manifest
+	// version always matches the release tag. Runners skip pre-release
+	// manifests after verifying them, so canaries stay test-only.
+	if (!/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/.test(clean)) {
+		throw new Error(`generate-runner-manifest: version must be semver (got '${version}').`);
+	}
+	const assets = [];
+	for (const [platform, arch] of SUPPORTED_TARGETS) {
+		const filename = `kainbain-runner-${clean}-${platform}-${arch}.tar.gz`;
+		const filePath = path.join(dir, filename);
+		if (!fs.existsSync(filePath)) {
+			throw new Error(`generate-runner-manifest: missing asset ${filename} in ${dir}.`);
+		}
+		const stat = fs.statSync(filePath);
+		assets.push({
+			platform,
+			arch,
+			filename,
+			sha256: sha256FileHex(filePath),
+			size: stat.size,
+		});
+	}
+	return {
+		schema: 1,
+		component: "runner",
+		version: clean,
+		releasedAt: new Date().toISOString(),
+		assetBase: `https://github.com/Ewrdad/Kainbain/releases/download/runner-v${clean}/`,
+		assets,
+		tag: tag || `runner-v${clean}`,
+	};
+};
+
+const main = () => {
+	const args = parseArgs(process.argv.slice(2));
+	const dir = path.resolve(args.dir || path.join(REPO_ROOT, "dist"));
+	const manifest = buildManifest({ version: args.version, dir, tag: args.tag });
+	const manifestText = `${JSON.stringify(manifest, null, 2)}\n`;
+	fs.writeFileSync(path.join(dir, "manifest.json"), manifestText);
+	const secret = String(process.env.RUNNER_RELEASE_SIGNING_KEY || "").trim();
+	const keynum = String(process.env.RUNNER_RELEASE_SIGNING_KEYNUM || "").trim();
+	if (!secret || !keynum) {
+		throw new Error(
+			"generate-runner-manifest: set RUNNER_RELEASE_SIGNING_KEY (base64/hex 32-byte seed) and RUNNER_RELEASE_SIGNING_KEYNUM (hex 8-byte id) from GitHub Secrets.",
+		);
+	}
+	const seedHex = /^[0-9a-fA-F]{64}$/.test(secret) ? secret.toLowerCase() : Buffer.from(secret, "base64").toString("hex");
+	fs.writeFileSync(
+		path.join(dir, "manifest.json.minisig"),
+		minisignSign({ messageBytes: Buffer.from(manifestText, "utf8"), secretSeedHex: seedHex, keynumHex: keynum }),
+	);
+	console.log(`manifest for ${manifest.version} signed (${manifest.assets.length} assets)`);
+};
+
+if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+	main();
+}
diff --git a/scripts/package-runner.mjs b/scripts/package-runner.mjs
new file mode 100644
index 0000000..f2486d0
--- /dev/null
+++ b/scripts/package-runner.mjs
@@ -0,0 +1,142 @@
+#!/usr/bin/env node
+/***
+ * MARK: package-runner
+ * @description Builds one versioned runner archive for the GitHub Releases
+ *   update channel (Option A, ADR 0012): copies the dependency-free runner
+ *   runtime tree (runner/, shared/, the harness modules under api/ it loads,
+ *   api/package.json) into a versioned dir, stamps runnerVersion into the
+ *   packaged version.json, and tars it as
+ *   kainbain-runner-<version>-<platform>-<arch>.tar.gz. The runtime closure
+ *   was verified npm-free except a lazy pi-SDK dynamic import (hosts that
+ *   serve pi models install it separately); tests, node_modules, secrets,
+ *   and VCS metadata are never packaged (CI fails the build if they leak).
+ * @example node scripts/package-runner.mjs --platform linux --arch x64 --version 1.2.3 --out dist/
+ ***/
+import { execFileSync } from "node:child_process";
+import fs from "node:fs";
+import path from "node:path";
+import { fileURLToPath } from "node:url";
+
+const HERE = path.dirname(fileURLToPath(import.meta.url));
+const REPO_ROOT = path.resolve(HERE, "..");
+
+const parseArgs = (argv) => {
+	const out = {};
+	for (let i = 0; i < argv.length; i += 1) {
+		const arg = argv[i];
+		if (arg.startsWith("--")) {
+			const key = arg.slice(2);
+			out[key] = argv[i + 1] && !argv[i + 1].startsWith("--") ? argv.splice(i + 1, 1)[0] : "true";
+		}
+	}
+	return out;
+};
+
+const FORBIDDEN_BASENAMES = new Set([".git", ".hg", "node_modules", ".env", ".env.local", "coverage", "dist"]);
+const FORBIDDEN_SUFFIXES = [".test.js", ".test.jsx", ".spec.js"];
+
+const copyPruned = (src, dest) => {
+	const stat = fs.statSync(src);
+	if (stat.isDirectory()) {
+		const base = path.basename(src);
+		if (FORBIDDEN_BASENAMES.has(base)) return;
+		fs.mkdirSync(dest, { recursive: true });
+		for (const entry of fs.readdirSync(src)) {
+			copyPruned(path.join(src, entry), path.join(dest, entry));
+		}
+		return;
+	}
+	const base = path.basename(src);
+	if (FORBIDDEN_SUFFIXES.some((suffix) => base.endsWith(suffix))) return;
+	fs.mkdirSync(path.dirname(dest), { recursive: true });
+	fs.copyFileSync(src, dest);
+};
+
+const assertClean = (stageDir) => {
+	const violations = [];
+	const walk = (dir) => {
+		for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
+			const full = path.join(dir, entry.name);
+			if (entry.isDirectory()) {
+				if (FORBIDDEN_BASENAMES.has(entry.name)) violations.push(full);
+				else walk(full);
+			} else if (
+				FORBIDDEN_SUFFIXES.some((suffix) => entry.name.endsWith(suffix)) ||
+				entry.name === ".env" ||
+				entry.name === ".env.local" ||
+				entry.name.endsWith(".minisig") && full.includes("secret")
+			) {
+				violations.push(full);
+			}
+		}
+	};
+	walk(stageDir);
+	if (violations.length > 0) {
+		throw new Error(`package-runner: forbidden files in archive:\n${violations.join("\n")}`);
+	}
+};
+
+export const packageRunner = ({ platform, arch, version, outDir, root = REPO_ROOT } = {}) => {
+	if (!["linux", "darwin"].includes(platform)) {
+		throw new Error(`package-runner: unsupported platform '${platform}' (v1: linux, darwin).`);
+	}
+	if (!["x64", "arm64"].includes(arch)) {
+		throw new Error(`package-runner: unsupported arch '${arch}' (v1: x64, arm64).`);
+	}
+	const clean = String(version || "").trim().replace(/^v/, "");
+	// Full semver incl. canary pre-releases (`1.2.3-rc.1`): the release
+	// workflow keeps the tag's suffix so a canary manifest never claims to
+	// be the final version it previews.
+	if (!/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/.test(clean)) {
+		throw new Error(`package-runner: version must be semver (got '${version}').`);
+	}
+	const name = `kainbain-runner-${clean}-${platform}-${arch}`;
+	const stage = path.join(outDir, name);
+	fs.rmSync(stage, { recursive: true, force: true });
+	fs.mkdirSync(stage, { recursive: true });
+	copyPruned(path.join(root, "runner"), path.join(stage, "runner"));
+	copyPruned(path.join(root, "shared"), path.join(stage, "shared"));
+	copyPruned(path.join(root, "api"), path.join(stage, "api"));
+	// Release metadata + entrypoint live at the archive root.
+	const versionJson = JSON.parse(fs.readFileSync(path.join(root, "runner", "version.json"), "utf8"));
+	versionJson.runnerVersion = clean;
+	fs.writeFileSync(path.join(stage, "version.json"), `${JSON.stringify(versionJson, null, 2)}\n`);
+	fs.writeFileSync(
+		path.join(stage, "INSTALL.txt"),
+		[
+			`kainbain-runner ${clean} (${platform}/${arch})`,
+			"",
+			"Install: extract under <install-root>/releases/<version>/unpacked",
+			"or point the wrapper at it: KAINBAIN_RUNNER_INSTALL_ROOT=<root>",
+			"runner/bin/kainbain-runner",
+			"",
+			"Hosts serving pi models also need @earendil-works/pi-coding-agent",
+			"resolvable from the archive's api/ dir (npm install --prefix api",
+			"--omit=dev inside the unpacked tree). All other harnesses and",
+			"the mock harness need only the host Node runtime.",
+			"",
+		].join("\n"),
+	);
+	assertClean(stage);
+	const tarball = path.join(outDir, `${name}.tar.gz`);
+	fs.rmSync(tarball, { force: true });
+	execFileSync("tar", ["-czf", tarball, "-C", outDir, name]);
+	return { name, tarball, version: clean, platform, arch };
+};
+
+const main = () => {
+	const args = parseArgs(process.argv.slice(2));
+	const outDir = path.resolve(args.out || path.join(REPO_ROOT, "dist"));
+	fs.mkdirSync(outDir, { recursive: true });
+	const result = packageRunner({
+		platform: args.platform,
+		arch: args.arch,
+		version: args.version,
+		outDir,
+	});
+	console.log(`packaged ${result.tarball}`);
+};
+
+if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+	main();
+}
